(function(){
'use strict';
document.documentElement.classList.add('perspective-enabled');
document.body.classList.add('forwarders-view');
const compactCss=document.createElement('link');compactCss.rel='stylesheet';compactCss.href='perspectives.css';document.head.appendChild(compactCss);
new ResizeObserver(()=>document.documentElement.style.setProperty('--perspective-header-height',document.querySelector('.site-header').getBoundingClientRect().height+'px')).observe(document.querySelector('.site-header'));
const api=window.VersionCompassForwarders,d=window.VersionCompassForwarderData,parsed=api.read(location.search),state=parsed.state;
let linkErrors=parsed.errors,model;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;'}[c]));
const themed=u=>window.VersionCompassTheme?.href(u)||u;
const names={uf:'Universal Forwarder',hf:'Heavy Forwarder',cmp:'CMP',cloud:'Splunk Cloud commercial','fr-m':'FR-M','fr-h':'FR-H',unspecified:'Not specified',x86_64:'x86-64',arm64:'ARM64',aws:'AWS',azure:'Azure',gcp:'Google Cloud',direct:'Direct',intermediate:'Intermediate forwarder',edge:'Edge Processor',other:'Other / not listed'};
const fields={type:'Forwarder',from:'Current',to:'Target',destination:'Destination',receiver:'Receiver version',os:'OS (exact release)',arch:'Architecture',provider:'Cloud provider',topology:'Topology'};
const evidence=(claim,key)=>{const s=d.sources[key];return s?window.VersionCompassEvidence.html({claim,scope:s.section,urls:[s.url],verified:s.reviewed}):'';};
const citation=key=>{const s=d.sources[key];return s?'<a href="'+esc(s.url)+'">'+esc(s.title)+'</a> · Checked '+esc(s.reviewed)+' · '+esc(s.section):'';};
const field=k=>'<label>'+esc(fields[k])+'<select data-forwarder="'+k+'">'+api.options[k].map(v=>'<option value="'+esc(v)+'">'+esc(names[v]||v)+'</option>').join('')+'</select></label>';
const products=document.querySelector('.product-switcher').outerHTML;
document.querySelector('main').innerHTML=`<section class="hero forwarder-hero"><div class="eyebrow">SPLUNK FORWARDERS</div><h1>Find your upgrade path</h1><div class="selector-card">${products}<div class="forwarder-primary">${['type','from','to','destination','receiver'].map(field).join('')}</div><details class="forwarder-advanced"><summary>Refine for your environment <span id="forwarder-filter-summary">OS, provider, region &amp; topology</span></summary><div class="forwarder-controls">${['os','arch','provider','topology'].map(field).join('')}<label>Destination region code<input data-forwarder="region" maxlength="50" placeholder="Optional, e.g. us-east-1" aria-describedby="forwarder-scope-note"></label></div><p id="forwarder-scope-note">CMP means customer-managed Splunk Enterprise, on premises or in your cloud. For an intermediate chain, assess each receiving hop separately. A region alone does not establish feature authorization.</p></details></div><div class="report-actions"><button id="copy-link" type="button">Copy comparison link</button><button id="print-report" type="button">Print / PDF</button><span id="share-status" role="status"></div></div></section><div id="forwarder-warnings" role="alert"></div><div id="results" tabindex="-1"></div><div id="release-report"></div>`;
document.querySelectorAll('input[name="product"]').forEach(el=>{el.checked=el.value==='forwarders';el.addEventListener('change',()=>{location.href=themed('?product='+el.value);});});
function status(c){return '<span class="forwarder-status status-'+esc(c.status)+'">'+esc(api.labels[c.status])+'</span>';}
function claim(c,intro){return '<article class="forwarder-fact"><div><h3>'+esc(intro||c.title)+'</h3>'+status(c)+'</div><p>'+esc(c.detail)+'</p>'+evidence(c.title+': '+c.detail,c.source)+'</article>';}
function availability(c){return '<div class="forwarder-availability" aria-label="Certificate renewal by destination">'+['cloud','cmp','fr-m','fr-h'].map(destination=>{const r=api.renewal({...state,destination});return '<div class="availability-item"><button type="button" data-evidence-trigger aria-label="'+esc(names[destination])+' certificate renewal details">'+esc(names[destination])+' · '+esc(api.labels[r.status])+'</button><div class="evidence-context" hidden><p>'+esc(r.detail)+'</p><p>'+citation(r.source)+'</p></div></div>';}).join('')+'</div>';}
function technical(t){return '<article class="forwarder-technical"><h4>'+esc(t.component)+(t.release?' · '+esc(t.release):'')+'</h4><p><strong>'+esc(t.changeType)+' · '+esc(t.actionLevel)+'</strong> · '+esc(t.from)+' → '+esc(t.to)+'</p><p>'+esc(t.implication)+'</p><p><strong>Action:</strong> '+esc(t.action)+'</p><a href="'+esc(t.source)+'">Official source ↗</a></article>';}
function briefReport(m){
 const route=m.path.length?m.path.map((v,i)=>'<span>'+esc(v)+'</span>').join('<span aria-hidden="true">→</span>'):'<strong>No recorded path</strong>';
 const stepSources=m.steps.map(s=>'<a href="'+esc(d.sources[s.source].url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.from+' → '+s.to)+'</a>').join(' · ');
 return `<section class="section forwarder-overview" id="route-takeaway"><div class="forwarder-section-head"><p class="kicker">YOUR ROUTE · ${esc(names[state.type])}</p><h2 id="path-title">${esc(state.from)} to ${esc(state.to)}</h2></div><div class="forwarder-path" aria-label="Documented release-line path">${route}</div><p class="forwarder-path-note">${esc(m.claims[0].detail)}</p><p class="forwarder-step-sources">Sources for each step: ${stepSources||citation(m.claims[0].source)}</p>${m.risks.length?'<div class="forwarder-alert"><strong>Watch for:</strong> '+esc(m.risks[0].detail)+' '+evidence(m.risks[0].title,m.risks[0].source)+'</div>':''}</section>
 <section class="section forwarder-compatibility"><h2 id="compatibility-title">Does this combination fit?</h2><div class="forwarder-facts">${claim(m.claims[1],names[state.destination]+' receiver '+(state.receiver==='unspecified'?'not specified':state.receiver))}${claim(m.os,'OS and architecture')}${claim(m.claims[2],'Authorization')}</div><p class="forwarder-scope">Receiver pairing, upgrade support, OS package support and authorization are separate checks. An unlisted combination remains <strong>Not established</strong>.</p></section>
 <section class="section forwarder-actions"><h2 id="readiness-title">Before you move</h2><ol class="forwarder-checks">${m.requiredChecks.map(x=>'<li>'+esc(x)+'</li>').join('')}</ol><div class="forwarder-two-col"><div><h3 id="value-title">Certificate renewal</h3><p>${status(m.features[0])} ${esc(m.features[0].detail)}</p>${evidence(m.features[0].title,m.features[0].source)}<p class="forwarder-secondary-label">Compare destinations</p>${availability(m.features[0])}</div><div><h3 id="breaking-title">Security and known issues</h3><p>${esc(m.security.detail)}</p>${evidence(m.security.title,m.security.source)}<p><a href="${esc(d.sources.known.url)}">Known issues ↗</a> · <a href="${esc(d.sources.fixed.url)}">Fixed issues ↗</a></p></div></div></section>
 <section class="section forwarder-technical-section"><details class="technical-panel" id="technical-panel"><summary><span id="technical-title">Technical requirements</span><span>Target package and changes along this route</span></summary><div class="forwarder-technical-body"><h3>At the target</h3><p>${esc(m.os.detail)}</p>${evidence(m.os.title,m.os.source)}<p>Bundled runtime changes do not establish add-on or app-owned runtime compatibility. Confirm exact premium-app patches separately.</p>${m.targetRuntime.map(technical).join('')}${state.type==='uf'?'<p>UF scripted-input and add-on runtimes require their own review; no Enterprise application-runtime change is assigned to UF.</p>':''}<h3>Along the route</h3>${m.technical.length?m.technical.map(technical).join(''):'<p>No additional component transition is curated for this interval. Review each intermediate release.</p>'}</div></details><p class="forwarder-coverage" id="source-title">${esc(m.coverage)} <a href="${esc(themed('?view=about'))}">Source register ↗</a></p></section>`;
}
function fullReport(m){
 const scope=Object.keys(api.defaults).map(k=>(fields[k]||'Region')+': '+(names[state[k]]||state[k])).join(' · ');
 const full=c=>'<article class="forwarder-record"><h3>'+esc(c.title)+' · '+esc(api.labels[c.status])+'</h3><p>'+esc(c.detail)+'</p><p>'+citation(c.source)+'</p></article>';
 return '<section class="section"><h2>Selected route</h2><p>'+esc(scope)+'</p><p>'+esc(m.coverage)+'</p>'+m.claims.map(full).join('')+'<h3>Documented steps</h3>'+m.steps.map(s=>'<p>'+esc(s.from+' → '+s.to)+' · '+citation(s.source)+'</p>').join('')+'</section>'+
 '<section class="section"><h2>Target environment and feature availability</h2>'+full(m.os)+m.features.map(c=>full(c)+availability(c)).join('')+'<p>Feature eligibility and authorization remain distinct. FR-M and FR-H are assessed independently.</p></section>'+
 '<section class="section"><h2>Target requirements</h2><p>Runtime history below identifies successive bundled changes through the target; later releases supersede older defaults. App-owned runtimes and premium-app patches require their own compatibility review.</p>'+m.targetRuntime.map(technical).join('')+(state.type==='uf'?'<p>No bundled Python or premium-app compatibility claim is established here for UF. Check scripted-input and add-on runtimes individually.</p>':'')+'<h2>Changes along the route</h2>'+(m.technical.length?m.technical.map(technical).join(''):'<p>No additional transition curated; this is not proof of no change.</p>')+'</section>'+
 '<section class="section"><h2>Known issues and security</h2>'+m.risks.map(full).join('')+full(m.security)+'<p>'+citation('known')+' · '+citation('fixed')+' · '+citation('advisories')+'</p><p>These issue directories and selected advisory floors are not an exhaustive patch inventory.</p></section>'+
 '<section class="section"><h2>Required checks</h2><ol>'+m.requiredChecks.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol><p>'+citation(state.type==='hf'?'enterprise':'upgrade104')+'</p></section>';
}
function render(){
 model=api.assess(state);const errors=[...linkErrors,...model.errors];
 document.getElementById('forwarder-warnings').innerHTML=errors.length?'<p>'+errors.map(esc).join('<br>')+'</p><button type="button" id="confirm-forwarder">Use the displayed selections</button>':'';
 for(const id of ['copy-link','print-report'])document.getElementById(id).disabled=!!errors.length;
 const results=document.getElementById('results');results.hidden=!!errors.length;
 if(errors.length){document.getElementById('confirm-forwarder').onclick=()=>{linkErrors=[];render();};return;}
 const technicalOpen=document.getElementById('technical-panel')?.open||false;
 results.innerHTML=briefReport(model);document.getElementById('technical-panel').open=technicalOpen;
 const refinements=['os','arch','provider','topology','region'].filter(k=>state[k]!=='unspecified'&&state[k]!=='direct');
 document.getElementById('forwarder-filter-summary').textContent=refinements.length?refinements.map(k=>names[state[k]]||state[k]).join(' · '):'OS, provider, region & topology';
 document.title='Version Compass | '+names[state.type]+' '+state.from+' → '+state.to;
 history.replaceState(null,'',themed(api.url(state)));
}
document.querySelectorAll('[data-forwarder]').forEach(el=>{el.value=state[el.dataset.forwarder]==='unspecified'&&el.tagName==='INPUT'?'':state[el.dataset.forwarder];el.addEventListener('change',()=>{state[el.dataset.forwarder]=el.value.trim()||'unspecified';linkErrors=[];render();});});
window.addEventListener('popstate',()=>{const next=api.read(location.search);Object.assign(state,next.state);linkErrors=next.errors;document.querySelectorAll('[data-forwarder]').forEach(e=>e.value=state[e.dataset.forwarder]==='unspecified'&&e.tagName==='INPUT'?'':state[e.dataset.forwarder]);render();});
document.getElementById('copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);document.getElementById('share-status').textContent='Comparison link copied.';}catch{document.getElementById('share-status').textContent='Copy this link: '+location.href;}};
window.VersionCompassBuildSnapshot=()=>{if(linkErrors.length||model.errors.length)throw Error('Resolve selection warnings first.');return window.VersionCompassReports.decorate('<h1>'+esc(document.title)+'</h1><p>Full selected forwarder report with requirements, route changes, issues, actions and citations.</p>'+fullReport(model));};
function prepare(){if(linkErrors.length||model.errors.length)return;document.getElementById('release-report').innerHTML=window.VersionCompassBuildSnapshot();document.documentElement.classList.add('printing-report');}
window.addEventListener('beforeprint',prepare);window.addEventListener('afterprint',()=>document.documentElement.classList.remove('printing-report'));
document.getElementById('print-report').onclick=()=>{prepare();window.print();};
render();
}());
/* Read-only page tool shares the exact report model. */
(function(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const api=window.VersionCompassForwarders;try{Promise.resolve(context.registerTool({name:'compare_forwarder_routes',title:'Compare forwarder routes',description:'Read evidence-backed forwarder upgrade, receiver, environment and requirements assessments. Does not change selections or certify readiness.',inputSchema:{type:'object',additionalProperties:false,required:['routes'],properties:{routes:{type:'array',minItems:1,maxItems:8,items:{type:'object',additionalProperties:false,properties:Object.fromEntries(Object.keys(api.defaults).map(k=>[k,k==='region'?{type:'string',pattern:'^[a-z0-9-]{1,50}$'}:{type:'string',enum:api.options[k]}]))}}}},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||!Array.isArray(input.routes)||input.routes.length<1||input.routes.length>8||Object.keys(input).some(k=>k!=='routes'))throw Error('Supply 1–8 routes.');return {revision:window.VersionCompassRevision,reports:input.routes.map(r=>{if(!r||typeof r!=='object'||Object.keys(r).some(k=>!(k in api.defaults)))throw Error('Invalid forwarder fields');return api.assess({...api.defaults,...r});}),sources:window.VersionCompassForwarderData.sources};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}());
